e planPrime and exactadmission; allPOST and unknown/replay/source/budget boundaries unchanged\\\",\\n    \\\"Register any additional productfiles separately beforecoding; no visual/business/wholeGoal completion; continue fullC genuineuserbudget/naturalbusiness/install/8scenarios/observe\\\"\\n  ],\\n  \\\"lease_expires_at\\\": \\\"2026-10-14T16:00:00+00:00\\\",\\n  \\\"owner\\\": \\\"codex-01a13484-f019-7d82-94ce-812396db9124\\\",\\n  \\\"schema\\\": \\\"aos-memory-task-receipt/v1\\\",\\n  \\\"scope\\\": [\\n    \\\"aos-platform/services/aos-api/aos_api/routers/ecommerce_workshop.py\\\",\\n    \\\"aos-platform/services/aos-api/tests/test_ecommerce_workshop_read_http.py\\\",\\n    \\\"aos-platform/.evidence/qyh-creator-workflow-read-admission-20261014\\\",\\n    \\\"docs/palantier/20_tech/电商平台接入/微商城电商接入方案/D-waves/2026-10-13-QYH-八台只读入口恢复与经营链接续清单.md\\\"\\n  ],\\n  \\\"status\\\": \\\"ACTIVE\\\",\\n  \\\"task_id\\\": \\\"qyh-creator-workflow-read-admission-20261014\\\"\\n}\\n\\nFILE .evidence/qyh-creator-workflow-read-admission-20261014/routing-implementation-plan.md SHA 81cb419dcbb34d611eea244a20c44705c5339f9176225bea687cf62f0e6fd933\\n# 达人内部草稿list GET精确接线方案\\n\\nRules/231完整Goal/unique m1/原数据只读；rootTask/base2030/16:00UTC scope router/read_http/evidence/D-wave，boundedreader另exactTask。同源bounded实现/114PASS/nativeRLS25006/concurrency/private/limits已具，code独立quality仍等待，未取得合法PASS前不加载。\\n\\n现helper已在上一波返回原typedreadiness；复用不重复scope/hash/roles算法。仅list_creator_internal_workflows GET改ReadCatalog+新lazy readonlydep，先query拒绝、原creator安装/roles/markings/dataScope准入，必须原typedresponse；UNKNOWN503READ_ADMISSION_UNAVAILABLE，不把None当空列表。只有服务端INSTALLED_ASSET_READONLY marker选择专用bounded.list(scope)，新reader错误固定503中文消息/code，不返回空200、不附私密/SQL。合法无marker保留原workflow.list(scope)和CreatorInternalWorkflowError旧映射。historyGET/所有executePOST/其他root/helper门完整不改，runtimeMode/limit/owner/query不能选择权限和读取。状态approved仅旧保存事实不操作许可。\\n\\nread_http先RED：原unreviewed workflowlist样例替换到其history；只加一GET白名单。新readiness合法fixture readonly→只新list、无marker→只旧list；catalog拒绝/query覆盖/None错型/四类reader503不空、typed成功六purpose或真正empty、HTTP所有其他GETPOST矩阵不变。root变更后专用/旧workflow/目录/HTTP累计及native现有同源fixture、独立quality合并证明。\\n\\n只候选代码，提交前冻结准确4sources和现有Store不改证明；之后最新已提交sourcefreeze/fresh维护控制器独立gate/一次API-only新label（不替代daily完整PG→API→Web），原真人正常GET/root菜单及threeviewport原稿/原650fingerprints/独立现场Prime后准确Delivery/AuthorityPrime。不能原DB造坏/新增草稿或真人假批准；原budgetC最终用户/自然经营链/安装生命周期/八场景/视觉P1/观察发布保持完整。\\n\\nFILE .evidence/qyh-creator-workflow-read-admission-20261014/routing-proposed-diff-r1.txt SHA 58ba4ded05984f1dab6fd04e04d792687f420ea2eae9258f41497570ac7b1170\\n--- services/aos-api/aos_api/routers/ecommerce_workshop.py CURRENT\\n+++ services/aos-api/aos_api/routers/ecommerce_workshop.py PROSPECTIVE NOT APPLIED\\n@@ -101,6 +101,9 @@\\n     ContentCampaignApprovalPreviewResponse,\\n     ContentCampaignWorkflowCommandRequest,\\n     ContentCampaignWorkflowCommandResponse,\\n+)\\n+from aos_api.ecommerce_creator_internal_workflow_readonly import (\\n+    CreatorInternalWorkflowReadonlyReader, CreatorWorkflowReadonlyError,\\n )\\n from aos_api.ecommerce_creator_internal_workflow import (\\n     CreatorInternalWorkflowConflict,\\n@@ -648,6 +651,16 @@\\n \\n CreatorLifecycleReadonlyDependency = Annotated[\\n     CreatorLifecycleReadonlyReader, Depends(get_creator_lifecycle_readonly)\\n+]\\n+\\n+\\n+@lru_cache(maxsize=1)\\n+def get_creator_workflow_readonly() -> CreatorInternalWorkflowReadonlyReader:\\n+    return CreatorInternalWorkflowReadonlyReader()\\n+\\n+\\n+CreatorWorkflowReadonlyDependency = Annotated[\\n+    CreatorInternalWorkflowReadonlyReader, Depends(get_creator_workflow_readonly)\\n ]\\n \\n \\n@@ -1600,13 +1613,22 @@\\n def list_creator_internal_workflows(\\n     request: Request,\\n     principal: PrincipalDependency,\\n-    catalog: CatalogDependency,\\n+    catalog: ReadCatalogDependency,\\n     workflow: CreatorInternalWorkflowDependency,\\n+    readonly: CreatorWorkflowReadonlyDependency,\\n ) -> CreatorInternalWorkflowListResponse:\\n     _reject_query_parameters(request)\\n-    _require_creator_growth_installation(principal=principal, catalog=catalog)\\n-    try:\\n-        return workflow.list(TenantScope(principal.org_id, principal.project_id))\\n+    admission = _require_creator_growth_installation(principal=principal, catalog=catalog)\\n+    if not isinstance(admission, EcommerceWorkshopModuleReadinessResponse):\\n+        raise ApiError(code=\\\"CREATOR_WORKFLOW_READ_ADMISSION_UNAVAILABLE\\\", message=\\\"当前内部草稿读取准入不可核验。\\\", status_code=503)\\n+    scope = TenantScope(principal.org_id, principal.project_id)\\n+    if any(b.reason_code == \\\"INSTALLED_ASSET_READONLY\\\" for b in admission.item.blockers):\\n+        try:\\n+            return readonly.list(scope)\\n+        except CreatorWorkflowReadonlyError as exc:\\n+            raise ApiError(code=exc.code, message=\\\"当前内部草稿暂不可读，请核对内容或读取范围。\\\", status_code=503) from exc\\n+    try:\\n+        return workflow.list(scope)\\n     except CreatorInternalWorkflowError as exc:\\n         raise _map_creator_internal_workflow_error(exc) from exc\\n \\n\\nFILE services/aos-api/tests/test_ecommerce_workshop_read_http.py SHA 3f7190e63d8843747ceb5f8e00baa1f336224160f54df03761cef72d3de5ec5e\\n\\\"\\\"\\\"HTTP scope fence: only explicitly audited GETs use installed read admission.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom fastapi import FastAPI\\nfrom fastapi.testclient import TestClient\\n\\nfrom aos_api.asset_registry.errors import AssetNotFoundError\\nfrom aos_api.auth import Principal, require_principal\\nfrom aos_api.errors import register_exception_handlers\\nfrom aos_api.routers import ecommerce_workshop as routes\\n\\nROOTS = {\\n    'task-cockpit', 'operations', 'content-campaign', 'creator-growth',\\n    'media-studio', 'analyst', 'price-governance', 'customer',\\n}\\n\\n\\nclass RejectingCatalog:\\n    def __init__(self):\\n        self.calls = []\\n\\n    def get_readiness(self, **scope):\\n        self.calls.append(scope)\\n        raise AssetNotFoundError('not installed in current scoped catalog')\\n\\n\\ndef client_with_catalogs():\\n    app = FastAPI()\\n    register_exception_handlers(app)\\n    app.include_router(routes.router)\\n    legacy, reader = RejectingCatalog(), RejectingCatalog()\\n    app.dependency_overrides[routes.get_ecommerce_workshop_catalog] = lambda: legacy\\n    app.dependency_overrides[routes.get_ecommerce_workshop_read_catalog] = lambda: reader\\n    app.dependency_overrides[require_principal] = lambda: Principal(\\n        subject='scope-test', org_id='org-org', project_id='dev-project',\\n        roles=['admin'], markings=[],\\n    )\\n    return TestClient(app), legacy, reader\\n\\n\\n@pytest.mark.parametrize('module', sorted(ROOTS))\\ndef test_root_get_uses_scoped_read_admission_before_business_reader(module):\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get(f'/v1/ecommerce-workshop/views/{module}')\\n    assert response.status_code == 404\\n    assert not legacy.calls\\n    assert len(reader.calls) == 1\\n    assert reader.calls[0] == dict(module_id=f'ecommerce.{module}',\\n        org_id='org-org', project_id='dev-project', roles=['admin'], markings=[])\\n\\n\\n@pytest.mark.parametrize('path', [\\n    '/views/customer/contributions', '/views/creator-growth/workflow/drafts',\\n    '/modules/ecommerce.operations/readiness',\\n])\\ndef test_unreviewed_get_still_uses_legacy_admission(path):\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get('/v1/ecommerce-workshop' + path)\\n    assert response.status_code == 404\\n    assert legacy.calls\\n    assert not reader.calls\\n\\n\\ndef test_read_dependency_only_reaches_explicit_audited_get_routes():\\n    actual = set()\\n    for route in routes.router.routes:\\n        uses_read = any(d.call is routes.get_ecommerce_workshop_read_catalog\\n                        for d in route.dependant.dependencies)\\n        if uses_read:\\n            assert route.methods == {'GET'}\\n            actual.add(route.path)\\n    assert actual == {f'/v1/ecommerce-workshop/views/{m}' for m in ROOTS} | {\\n        '/v1/ecommerce-workshop/source-readiness',\\n        '/v1/ecommerce-workshop/views/operations/cases',\\n        '/v1/ecommerce-workshop/commands/operations/readiness',\\n        '/v1/ecommerce-workshop/views/task-cockpit/feedback',\\n        '/v1/ecommerce-workshop/views/task-cockpit/dispatch-scenario',\\n        '/v1/ecommerce-workshop/views/task-cockpit/batch-scenario',\\n        '/v1/ecommerce-workshop/views/media-studio/full-production-scenario',\\n        '/v1/ecommerce-workshop/views/media-studio/workflow/drafts',\\n        '/v1/ecommerce-workshop/views/analyst/learning-scenario',\\n        '/v1/ecommerce-workshop/views/content-campaign/real-inputs',\\n        '/v1/ecommerce-workshop/views/creator-growth/contributions',\\n        '/v1/ecommerce-workshop/views/creator-growth/lifecycle',\\n    }\\n\\n\\ndef test_unknown_query_rejected_before_catalog_call():\\n    client, legacy, reader = client_with_catalogs()\\n    assert client.get('/v1/ecommerce-workshop/views/operations?orgId=dev-org').status_code == 400\\n    assert not legacy.calls and not reader.calls\\n\\n\\nclass ReadReached(RuntimeError):\\n    pass\\n\\n\\ndef test_creator_contribution_read_denied_before_service_access():\\n    client, legacy, reader = client_with_catalogs()\\n    class Service:\\n        def contribution_view(self, scope):\\n            pytest.fail('denied read must not access creator preparation')\\n    client.app.dependency_overrides[routes.get_ecommerce_workshop_creator_prepare] = lambda: Service()\\n    response = client.get('/v1/ecommerce-workshop/views/creator-growth/contributions')\\n    assert response.status_code == 404\\n    assert not legacy.calls\\n    assert reader.calls == [dict(module_id='ecommerce.creator-growth',\\n        org_id='org-org', project_id='dev-project', roles=['admin'], markings=[])]\\n\\n\\ndef test_admitted_creator_contribution_receives_authenticated_scope():\\n    client, legacy, reader = client_with_catalogs()\\n    def admit(**scope):\\n        reader.calls.append(scope)\\n    reader.get_readiness = admit\\n    class Service:\\n        def contribution_view(self, scope):\\n            assert scope.key == ('org-org', 'dev-project')\\n            raise ReadReached('creator-contribution')\\n    client.app.dependency_overrides[routes.get_ecommerce_workshop_creator_prepare] = lambda: Service()\\n    with pytest.raises(ReadReached, match='creator-contribution'):\\n        client.get('/v1/ecommerce-workshop/views/creator-growth/contributions')\\n    assert not legacy.calls and len(reader.calls) == 1\\n\\n\\ndef test_creator_contribution_query_scope_override_is_rejected():\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get('/v1/ecommerce-workshop/views/creator-growth/contributions?projectId=other')\\n    assert response.status_code == 400\\n    assert not legacy.calls and not reader.calls\\n\\n\\ndef test_real_inputs_read_denied_before_business_data_access():\\n    client, legacy, reader = client_with_catalogs()\\n    def forbidden_inputs():\\n        class Inputs:\\n            def read(self, **scope):\\n                pytest.fail('denied installed read must not read business inputs')\\n        return Inputs()\\n    client.app.dependency_overrides[routes.get_ecommerce_workshop_content_campaign_inputs] = forbidden_inputs\\n    response = client.get('/v1/ecommerce-workshop/views/content-campaign/real-inputs')\\n    assert response.status_code == 404\\n    assert not legacy.calls\\n    assert reader.calls == [dict(module_id='ecommerce.content-campaign',\\n        org_id='org-org', project_id='dev-project', roles=['admin'], markings=[])]\\n\\n\\ndef test_admitted_real_inputs_receives_only_authenticated_tenant():\\n    client, legacy, reader = client_with_catalogs()\\n    def admit(**scope):\\n        reader.calls